private static let calendar = Calendar(identifier: .gregorian)
private static let jan1 = calendar.date(from: DateComponents(year: 2026, month: 1, day: 1)) ?? .distantPast
private static func day(_ offset: Int) -> Date {
    calendar.date(byAdding: .day, value: offset, to: jan1) ?? jan1
}

@State private var items = [
    MonarchRoadmapItem(id: "p3", label: "Help centre search", start: day(32), end: day(119), health: .atRisk),
]
@State private var state = MonarchGanttTimelineState(view: .list)

examples.code:
MonarchRoadmap(
    items,
    state: $state,
    today: nil,
    showsToolbar: false,
    onChange: { item, dates in
        guard let index = items.firstIndex(where: { $0.id == item.id }) else { return }
        items[index].start = dates.start
        items[index].end = dates.end
        // The app saves item.id with dates.start and dates.end here.
    }
)
.environment(\.calendar, Self.calendar)
